WITH catalog_total AS (SELECT COUNT(DISTINCT product_id) AS total_products FROM fashion.catalog.products) SELECT p.master_category AS master_category, p.sub_category AS sub_category, COUNT(DISTINCT p.product_id) AS product_count, ROUND(100.0 * COUNT(DISTINCT p.product_id) / t.total_products, 2) AS catalog_share_pct FROM fashion.catalog.products p CROSS JOIN catalog_total t WHERE p.master_category IS NOT NULL AND TRIM(p.master_category) <> '' AND p.sub_category IS NOT NULL AND TRIM(p.sub_category) <> '' AND p.product_id IS NOT NULL GROUP BY p.master_category, p.sub_category, t.total_products ORDER BY product_count DESC, p.master_category ASC, p.sub_category ASC LIMIT 15
